import React, {
  forwardRef,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from 'react';
import { createPortal } from 'react-dom';
import { FormattedMessage, useIntl } from 'react-intl';
import { isElement } from 'react-is';
import styled from 'styled-components';

import Borders from '@dynatrace/strato-design-tokens/borders';
import Colors from '@dynatrace/strato-design-tokens/colors';
import Elevations from '@dynatrace/strato-design-tokens/elevations';
import Spacings from '@dynatrace/strato-design-tokens/spacings';

import { MicroguideContext } from './contexts/MicroguideContext.js';
import { Step } from './Step.js';
import { Button } from '../../buttons/button/Button.js';
import { _useAriaLabelingProps } from '../../core/hooks/useAriaLabelingProps.js';
import { useOverlayStacking } from '../../core/hooks/useOverlayStacking.js';
import { _useSafeForwardProps } from '../../core/hooks/useSafeForwardProps.js';
import type { AriaLabelingProps } from '../../core/types/a11y-props.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { Flex } from '../../layouts-core/flex/Flex.js';
import { Surface } from '../../layouts-core/surface/Surface.js';
import { useKeyboardFocusHandling } from '../hooks/useKeyboardFocusHandling.js';
import { Content } from '../shared-components/Content.js';
import { Title } from '../shared-components/Title.js';
import { Visual } from '../shared-components/Visual.js';

// #region Typings
/** Accepted properties for Microguide */
export interface MicroguideProps extends WithChildren, AriaLabelingProps {
  /**
   * Whether the Microguide is currently shown or not. Has to be controlled by the consumer.
   */
  open: boolean;
  /**
   * Placement of the Microguide.
   * @defaultValue 'bottom-right'
   */
  placement?: 'bottom-right' | 'bottom-left' | 'top-right' | 'top-left';
  /**
   * Callback fired when closing the Microguide.
   * Indicates the current step when closing and whether the Microguide was finished (closed in the last step).
   */
  onClose: (currentStep: number, finished: boolean) => void;
}
// #endregion Typings

// #region StyledComponents
function getPositionStyle(
  placement: 'bottom-right' | 'bottom-left' | 'top-right' | 'top-left',
) {
  switch (placement) {
    case 'bottom-left':
      return {
        bottom: Spacings.Size16,
        left: Spacings.Size16,
      };
    case 'top-right':
      return {
        top: Spacings.Size16,
        right: Spacings.Size16,
      };
    case 'top-left':
      return {
        top: Spacings.Size16,
        left: Spacings.Size16,
      };
    case 'bottom-right':
    default:
      return {
        bottom: Spacings.Size16,
        right: Spacings.Size16,
      };
  }
}

const MicroguideWrapper = /* @__PURE__ */ styled(Surface)<{
  $placement: 'bottom-right' | 'bottom-left' | 'top-right' | 'top-left';
  $zIndex: number;
}>(({ $placement, $zIndex }) => ({
  position: 'fixed',
  width: '400px',
  maxWidth: `calc(100vw - ${Spacings.Size32})`,
  maxHeight: `calc(100vh - ${Spacings.Size32})`,
  padding: Spacings.Size0,
  borderRadius: Borders.Radius.Surface.Subdued,
  zIndex: $zIndex,
  ...getPositionStyle($placement),

  '&::before, &::after, & .surface-background, & .surface-background::before, & .surface-background::after':
    {
      borderRadius: Borders.Radius.Surface.Subdued,
    },
}));

const StepIndicator = /* @__PURE__ */ styled.div({
  color: Colors.Text.Neutral.Subdued,
});

const MicroguideFooter = /* @__PURE__ */ styled(Flex)({
  zIndex: Elevations.Default,
  position: 'relative',
});
// #endregion StyledComponents

/** Microguide component */
export const _Microguide = forwardRef<HTMLElement, MicroguideProps>(
  (props, forwardedRef) => {
    const {
      open,
      placement = 'bottom-right',
      onClose,
      children,
      ...remainingProps
    } = props;
    const microguideContainer = useRef<HTMLElement | null>(null);
    const closeButtonRef = useRef<HTMLButtonElement | null>(null);
    const steps: React.ReactNode[] = [];
    const [currentStep, setCurrentStep] = useState(0);
    const [isNext, setIsNext] = useState(true);
    const [hasTitle, setHasTitle] = useState(false);
    const [hasContent, setHasContent] = useState(false);
    const [handleFocusOnKeydown, closedOnKeydown] =
      useKeyboardFocusHandling(closeButtonRef);
    const overlayStacking = useOverlayStacking(undefined, 'microguide');
    const intl = useIntl();
    const ariaLabelingProps = _useAriaLabelingProps(remainingProps);
    const forwardProps = _useSafeForwardProps(
      remainingProps,
      ariaLabelingProps,
    );

    React.Children.forEach(children, (child) => {
      if (isElement(child) && child.type === Step) {
        steps.push(child);
      } else {
        // eslint-disable-next-line no-console
        console.warn('Only Step is a valid child of the Microguide.');
      }
    });

    const isLastStep = currentStep + 1 >= steps.length;
    if (hasTitle && ariaLabelingProps['aria-labelledby'] === undefined) {
      ariaLabelingProps['aria-labelledby'] = 'strato-microguide-title';
    }
    if (hasContent && ariaLabelingProps['aria-describedby'] === undefined) {
      ariaLabelingProps['aria-describedby'] = 'strato-microguide-content';
    }

    // Handle the escape key
    const closeOnEscape = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        e.preventDefault();
        closedOnKeydown.current = true;
        onClose(currentStep, currentStep === steps.length);
      }
    };

    useLayoutEffect(() => {
      const toastContainer = document.querySelector('[data-toast-container]');
      microguideContainer.current = document.createElement('div');
      microguideContainer.current.setAttribute('aria-live', 'polite');
      microguideContainer.current.setAttribute(
        'data-microguide-container',
        'true',
      );

      if (toastContainer && toastContainer.parentNode) {
        toastContainer.parentNode.insertBefore(
          microguideContainer.current,
          toastContainer,
        );
      } else {
        document.body.appendChild(microguideContainer.current);
      }

      return () => {
        microguideContainer.current?.remove();
      };
    }, []);

    useEffect(() => {
      // Reset microguide to the first page once it closes
      if (open === false) {
        setCurrentStep(0);
        // handle focus if closed via keyboard
        handleFocusOnKeydown();
      }
    }, [handleFocusOnKeydown, open]);

    return open
      ? createPortal(
          <MicroguideWrapper
            $placement={placement}
            $zIndex={overlayStacking.style.zIndex}
            elevation="floating"
            onKeyDown={closeOnEscape}
            role="dialog"
            aria-modal="false"
            ref={forwardedRef}
            {...forwardProps}
            {...ariaLabelingProps}
          >
            <MicroguideContext.Provider
              value={{
                onClose,
                currentStep,
                totalSteps: steps.length,
                isNext,
                setHasContent,
                setHasTitle,
                closeButtonRef,
                closedOnKeydown,
              }}
            >
              {steps[currentStep]}
            </MicroguideContext.Provider>
            <MicroguideFooter
              flexDirection="row"
              justifyContent="space-between"
              alignItems="center"
              gap={16}
              paddingX={16}
              paddingBottom={16}
              paddingTop={8}
            >
              <StepIndicator>
                {steps.length > 1 && `${currentStep + 1}/${steps.length}`}
              </StepIndicator>
              <Flex gap={8}>
                {currentStep > 0 && (
                  <Button
                    onClick={() => {
                      setIsNext(false);
                      setCurrentStep(currentStep - 1);
                    }}
                  >
                    <FormattedMessage
                      description="Microguide Back button."
                      defaultMessage="Back"
                      id="N27hQ6LyGqdym2Yi"
                    />
                  </Button>
                )}
                <Button
                  variant={isLastStep ? 'accent' : 'emphasized'}
                  color={isLastStep ? 'primary' : 'neutral'}
                  onClick={
                    isLastStep
                      ? () => onClose(currentStep, true)
                      : () => {
                          setIsNext(true);
                          setCurrentStep(currentStep + 1);
                        }
                  }
                  onKeyDown={() => (closedOnKeydown.current = isLastStep)}
                >
                  {isLastStep
                    ? intl.formatMessage({
                        defaultMessage: 'Got it',
                        id: 'fzkORq3AsvX/NtMB',
                        description: 'Microguide Got it button at last step.',
                      })
                    : intl.formatMessage({
                        defaultMessage: 'Next',
                        id: '+jn6HNnzB4IDIbZu',
                        description: 'Microguide Next button.',
                      })}
                </Button>
              </Flex>
            </MicroguideFooter>
          </MicroguideWrapper>,
          microguideContainer.current || document.body,
        )
      : null;
  },
);

(_Microguide as typeof _Microguide & { displayName: string }).displayName =
  'Microguide';

/**
 * The `Microguide` supports the onboarding of new users, as well as the introduction of new features to existing users.
 * It can have one or multiple steps, each of which has three optional slots: `Title`, `Visual` and `Content`.
 */
export const Microguide = Object.assign(_Microguide, {
  Step,
  Title,
  Visual,
  Content,
});
